const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;padding:8px;color:var(--ink);font:12px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.card *{box-sizing:border-box}\n.card[data-size=\"6x6\"]{padding:12px;font-size:13px}\n.lv,.dv,.fv{flex:1 1 auto;min-width:0;min-height:0;display:flex;flex-direction:column}\n.btn{font:inherit;min-height:28px;padding:3px 10px;border-radius:8px;border:1px solid var(--line);background:var(--button-paper,var(--paper));color:var(--ink);cursor:pointer;white-space:nowrap}\n.btn.pri{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.btn:disabled{opacity:.55;cursor:default}\n.btn:focus-visible,.chip:focus-visible,.row:focus-visible,.inp:focus-visible,.x:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.inp{font:inherit;width:100%;min-width:0;min-height:28px;padding:3px 7px;border-radius:8px;border:1px solid var(--line);background:var(--paper);color:var(--ink)}\n.inp::placeholder{color:var(--muted)}\n.ta{min-height:64px;resize:none;display:block}\n.chip{font:inherit;font-size:11.5px;min-height:24px;padding:1px 9px;border-radius:999px;border:1px solid var(--line);background:var(--button-paper,var(--paper));color:var(--ink);cursor:pointer;white-space:nowrap}\n.chip[aria-pressed=\"true\"]{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.chips{display:flex;flex-wrap:wrap;gap:4px;margin-top:5px}\n.chips.topics{max-height:60px;overflow:auto;align-content:flex-start}\n.top{display:flex;flex-wrap:wrap;align-items:center;gap:5px;flex:0 0 auto}\n.ttl{order:0;flex:1 1 auto;min-width:0;display:flex;align-items:center;gap:5px;font-size:1.1em;white-space:nowrap;overflow:hidden}\n.cnt{color:var(--muted);font-size:11px}\n.x{font:inherit;width:20px;height:20px;line-height:1;padding:0;border-radius:50%;border:1px solid var(--line);background:var(--button-paper,var(--paper));color:var(--ink);cursor:pointer}\n.add{order:1}\n.search{order:2;flex:1 1 100%}\n.tsel{order:3;flex:1 1 100%}\n.rows{flex:1 1 auto;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:5px;margin-top:6px;padding-right:2px}\n.row{display:block;flex:0 0 auto;width:100%;min-width:0;text-align:left;font:inherit;color:inherit;background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;padding:6px 8px;cursor:pointer}\n.row:hover{border-color:var(--accent)}\n.r-l1{display:flex;align-items:center;gap:6px;min-width:0}\n.r-name{flex:1 1 0;min-width:3em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}\n.r-tp{display:none;flex:0 1 auto;max-width:40%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:11px}\n.mk{flex:0 0 auto;width:19px;height:19px;display:inline-grid;place-items:center;border-radius:6px;border:1px solid var(--accent);color:var(--accent);background:var(--soft);font-size:11px;font-weight:700}\n.tag{flex:0 0 auto;font-size:10.5px;line-height:16px;padding:0 7px;border-radius:999px;border:1px solid var(--line);color:var(--muted);white-space:nowrap}\n.tag.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.r-l2,.r-l3,.r-note,.r-hit{display:none;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:11px;margin-top:2px}\n.r-l3,.r-hit{display:block}\n.r-l3 span+span::before{content:\" \u00b7 \"}\n.r-l3 .upd{color:var(--accent-alt);font-weight:600}\n.r-loc,.wd{display:none}\n.r-hit{color:var(--ink)}\n.empty{display:flex;flex-direction:column;align-items:flex-start;gap:6px;padding:10px 4px;color:var(--muted)}\n.empty b{color:var(--ink)}\n.card[data-size=\"3x3\"] .ttl{font-size:1em}\n.card[data-size=\"3x3\"] .search{flex:1 1 70px;min-width:0}\n.card[data-size=\"3x3\"] .tsel{flex:0 1 82px;min-width:0}\n.card[data-size=\"3x3\"] .search{order:2}\n.card[data-size=\"3x3\"] .tsel{order:3}\n.card[data-size=\"3x3\"] .btn.add{padding:3px 8px}\n.card[data-size=\"3x3\"] .row{padding:5px 7px}\n.card[data-size=\"3x6\"] .r-l2,.card[data-size=\"6x6\"] .r-l2{display:block}\n.card[data-size=\"6x3\"] .r-tp{display:block}\n.card[data-size=\"6x3\"] .r-loc,.card[data-size=\"6x6\"] .r-loc,.card[data-size=\"6x3\"] .wd,.card[data-size=\"6x6\"] .wd{display:inline}\n.card[data-size=\"6x6\"] .r-note{display:block}\n.card[data-size=\"6x3\"] .search{order:1;flex:1 1 120px}\n.card[data-size=\"6x3\"] .tsel{order:2;flex:0 0 130px}\n.card[data-size=\"6x3\"] .add{order:3}\n.card[data-size=\"6x3\"] .ttl{flex:0 0 auto}\n\n.dv-h{flex:0 0 auto;display:flex;align-items:center;gap:6px;min-width:0;padding-bottom:6px;border-bottom:1px solid var(--line)}\n.back{min-width:30px;padding:3px 8px;font-size:1.2em;line-height:1}\n.dv-t{flex:1 1 0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:1.08em}\n.dv-b,.fv-b{flex:1 1 auto;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px;padding:8px 2px 2px 0}\n.dv-m{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.hint{font-size:11.5px;padding:5px 8px;border-radius:8px;background:var(--soft);color:var(--ink);overflow-wrap:anywhere}\n.err{font-size:11.5px;padding:5px 8px;border-radius:8px;border:1px dashed var(--ink);color:var(--ink);overflow-wrap:anywhere}\n.dv-a,.vc-a{display:flex;flex-wrap:wrap;align-items:center;gap:5px}\n.ask{flex:1 1 100%;font-size:11.5px;overflow-wrap:anywhere}\n.vc{flex:0 0 auto;display:flex;flex-direction:column;gap:5px;min-width:0;padding:8px;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper)}\n.vc.on{border-color:var(--accent);box-shadow:inset 3px 0 0 var(--accent)}\n.vc-h{display:flex;align-items:center;gap:6px;flex-wrap:wrap}\n.vc-d{font-size:1.05em;font-variant-numeric:tabular-nums}\n.kv{display:flex;gap:6px;min-width:0}\n.lb{flex:0 0 auto;width:2.6em;color:var(--muted);font-size:11px}\n.pth{flex:1 1 0;min-width:0;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:11.5px;overflow-wrap:anywhere;word-break:break-all}\n.nt{flex:1 1 0;min-width:0;white-space:pre-wrap;overflow-wrap:anywhere}\n.nt.empty{color:var(--muted)}\n.fv-b{gap:8px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fld-g{display:flex;flex-direction:column;min-width:0}\n.fl{color:var(--muted);font-size:11px}\n.sec{font-weight:700;padding-top:4px;border-top:1px solid var(--line)}\n.ck{display:flex;align-items:center;gap:7px;min-height:28px}\n.ck input{width:16px;height:16px;margin:0;accent-color:var(--accent)}\n.sug{margin-top:4px;max-height:52px;overflow:auto;align-content:flex-start}\n.fv-f{flex:0 0 auto;display:flex;gap:6px;padding-top:6px;border-top:1px solid var(--line)}\n.fv-f .btn{flex:1 1 0}\n.card[data-size=\"3x3\"] .dv-b,.card[data-size=\"3x3\"] .fv-b{gap:5px;padding-top:5px}\n.card[data-size=\"3x3\"] .vc{padding:6px}\n.card[data-size=\"3x3\"] .fv-b .chip{min-height:22px;padding:0 7px}\n.card[data-size=\"3x3\"] .btn{padding:2px 7px;min-height:26px}\n.card[data-size=\"6x3\"] .fv-b{display:grid;grid-template-columns:1fr 1fr;gap:6px 10px;align-content:start}\n.card[data-size=\"6x3\"] .fv-b>.sec,.card[data-size=\"6x3\"] .fv-b>.err,.card[data-size=\"6x3\"] .fv-b>.ck{grid-column:1/-1}\n.card[data-size=\"6x3\"] .ta{min-height:44px}\n.card[data-size=\"6x3\"] .dv-b{display:block}\n.card[data-size=\"6x3\"] .dv-b>*{margin-bottom:6px}\n.card[data-size=\"6x6\"] .vc{padding:10px}\n";
var KINDS=[{id:'table',label:'数据表',mark:'表'},{id:'chart',label:'图表',mark:'图'},{id:'doc',label:'文稿',mark:'稿'}];
var NONE='__none__';
function kindOf(id){for(var i=0;i<KINDS.length;i++){if(KINDS[i].id===id)return KINDS[i];}return KINDS[0];}
function mats(s){return s&&Array.isArray(s.materials)?s.materials:[];}
function vers(m){return Array.isArray(m.versions)?m.versions:[];}
function sortedVers(m){
  return vers(m).map(function(v,i){return {v:v,i:i};}).sort(function(a,b){
    if(a.v.date!==b.v.date)return a.v.date<b.v.date?1:-1;
    return b.i-a.i;
  }).map(function(x){return x.v;});
}
function adoptedOf(m){
  var vs=vers(m);
  for(var i=0;i<vs.length;i++){if(vs[i].id===m.currentId)return vs[i];}
  return null;
}
function newestOf(m){var a=sortedVers(m);return a.length?a[0]:null;}
function topicOf(m){return String(m.topic||'').trim();}
function okDate(d){return /^\d{4}-\d{2}-\d{2}$/.test(String(d||''));}
function topicsOf(ms){
  var map={},none=0;
  ms.forEach(function(m){var t=topicOf(m);if(t){map[t]=(map[t]||0)+1;}else{none++;}});
  var list=Object.keys(map).sort(function(a,b){return a.localeCompare(b,'zh');}).map(function(t){return {id:t,n:map[t]};});
  return {list:list,none:none};
}
function haystack(m){
  var parts=[m.name,topicOf(m),kindOf(m.kind).label];
  vers(m).forEach(function(v){parts.push(v.date,v.location,v.note);});
  return parts.join('\n').toLowerCase();
}
function matchedVersion(m,q){
  if(!q)return null;
  var sv=sortedVers(m);
  for(var i=0;i<sv.length;i++){
    var t=[sv[i].date,sv[i].location,sv[i].note].join('\n').toLowerCase();
    if(t.indexOf(q)>=0)return sv[i];
  }
  return null;
}
function listFor(ms,f){
  var q=String(f.q||'').trim().toLowerCase();
  var out=ms.filter(function(m){
    var t=topicOf(m);
    if(f.topic){
      if(f.topic===NONE){if(t)return false;}
      else if(t!==f.topic)return false;
    }
    if(f.kind&&m.kind!==f.kind)return false;
    if(f.onlyAdopted&&!adoptedOf(m))return false;
    if(q&&haystack(m).indexOf(q)<0)return false;
    return true;
  });
  out.sort(function(a,b){
    var da=(newestOf(a)||{}).date||'',db=(newestOf(b)||{}).date||'';
    if(da!==db)return da<db?1:-1;
    return String(a.name).localeCompare(String(b.name),'zh');
  });
  return out;
}
function patchMat(s,mid,fn){
  return Object.assign({},s,{materials:mats(s).map(function(m){return m.id===mid?fn(m):m;})});
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const ms=mats(state);

  function h(tag,cls,kids,extra){
    var a=Object.assign({class:cls||''},extra||{});
    var list=(kids||[]).filter(function(k){return k!==null&&k!==undefined&&k!==false&&k!=='';});
    return el(tag,a,...list);
  }
  function btn(label,fn,o){
    o=o||{};
    var a={type:'button',class:'btn'+(o.pri?' pri':'')+(o.cls?' '+o.cls:''),onclick:fn};
    if(o.dis)a.disabled=true;
    if(o.aria)a['aria-label']=o.aria;
    return el('button',a,label);
  }
  function chip(label,on,fn,aria){
    var a={type:'button',class:'chip',onclick:fn,'aria-pressed':on?'true':'false'};
    if(aria)a.title=aria;
    return el('button',a,label);
  }
  function clear(node){while(node.firstChild)node.removeChild(node.firstChild);}
  function go(p){Object.assign(ui,p);redraw();}
  function fail(msg){ui.err=msg;redraw();return msg;}
  function mark(m){var k=kindOf(m.kind);return h('span','mk',[k.mark],{title:k.label});}
  function errBox(){return ui.err?h('div','err',['⚠ '+ui.err],{role:'alert'}):null;}
  function filterActive(){return !!(String(ui.q||'').trim()||ui.topic||ui.kind||ui.onlyAdopted);}
  function resetFilter(){go({q:'',topic:'',kind:'',onlyAdopted:false});}

  function rowFor(m,q){
    var ad=adoptedOf(m),nw=newestOf(m),hit=matchedVersion(m,q);
    var t=topicOf(m);
    var l1=h('div','r-l1',[mark(m),h('span','r-name',[m.name],{title:m.name}),t?h('span','r-tp',[t]):null,ad?h('span','tag on',['采用']):null]);
    var l2=h('div','r-l2',[(t||'未归类主题')+' · '+vers(m).length+' 个版本']);
    var l3parts=[];
    if(ad){
      l3parts.push(h('span','',['采用 '+ad.date]));
      if(nw&&nw.id!==ad.id&&nw.date>ad.date)l3parts.push(h('span','upd',['有新版',h('span','wd',[' '+nw.date])]));
      l3parts.push(h('span','r-loc',[ad.location]));
    }else{
      l3parts.push(h('span','',['未标采用']));
      if(nw)l3parts.push(h('span','',['最新 '+nw.date]));
      if(nw)l3parts.push(h('span','r-loc',[nw.location]));
    }
    var l3=h('div','r-l3',l3parts);
    var note=ad||nw;
    var l4=note&&note.note?h('div','r-note',['改动：'+note.note]):null;
    var l5=hit?h('div','r-hit',['命中 '+hit.date+' · '+(hit.note||hit.location)]):null;
    return h('button','row',[l1,l2,l3,l4,l5],{type:'button',onclick:function(){go({view:'detail',sel:m.id,confirm:'',err:''});}});
  }

  function listView(){
    var tp=topicsOf(ms);
    if(ui.topic&&ui.topic!==NONE&&!tp.list.some(function(t){return t.id===ui.topic;}))ui.topic='';
    if(ui.topic===NONE&&!tp.none)ui.topic='';
    var big=size==='6x6',tall=size==='3x6';

    var countEl=h('small','cnt',['']);
    var clr=el('button',{type:'button',class:'x','aria-label':'清除筛选',title:'清除筛选',onclick:resetFilter},'×');
    var box=h('div','rows');
    var qin=el('input',{class:'inp search',type:'search',value:ui.q||'',placeholder:'搜名称、位置、改动',
      oninput:function(){ui.q=qin.value;fill();}});

    function fill(){
      clear(box);
      var q=String(ui.q||'').trim().toLowerCase();
      var rows=listFor(ms,ui);
      var act=filterActive();
      countEl.textContent=act?(rows.length+'/'+ms.length):String(ms.length);
      clr.style.display=act?'':'none';
      if(!ms.length){
        box.appendChild(h('div','empty',[h('b','',['还没有登记材料']),h('span','',['点右上角“登记”，记下第一份数据表、图表或文稿的位置与版本。'])]));
        return;
      }
      if(!rows.length){
        box.appendChild(h('div','empty',[h('b','',['没有符合条件的材料']),btn('清除筛选',resetFilter)]));
        return;
      }
      rows.forEach(function(m){box.appendChild(rowFor(m,q));});
    }

    var opts=[el('option',{value:''},'全部主题')];
    tp.list.forEach(function(t){opts.push(el('option',{value:t.id},t.id+' ('+t.n+')'));});
    if(tp.none)opts.push(el('option',{value:NONE},'未归类 ('+tp.none+')'));
    var sel=el('select',{class:'inp tsel','aria-label':'按研究主题查找',onchange:function(){ui.topic=sel.value;fill();}},...opts);
    sel.value=ui.topic||'';

    var top=h('div','top',[
      h('div','ttl',[h('b','',['材料目录']),countEl,clr]),
      btn('＋ 登记',function(){openNewMat();},{pri:true,cls:'add',aria:'登记新材料'}),
      qin,
      big?null:sel
    ]);
    var parts=[top];
    if(big){
      var tc=[chip('全部主题',!ui.topic,function(){go({topic:''});})];
      tp.list.forEach(function(t){tc.push(chip(t.id+' '+t.n,ui.topic===t.id,function(){go({topic:ui.topic===t.id?'':t.id});}));});
      if(tp.none)tc.push(chip('未归类 '+tp.none,ui.topic===NONE,function(){go({topic:ui.topic===NONE?'':NONE});}));
      parts.push(h('div','chips topics',tc));
    }
    if(big||tall){
      var kc=[chip(big?'全部类型':'全部',!ui.kind,function(){go({kind:''});})];
      KINDS.forEach(function(k){kc.push(chip(big?k.label:k.mark,ui.kind===k.id,function(){go({kind:ui.kind===k.id?'':k.id});},k.label));});
      kc.push(chip('仅已采用',!!ui.onlyAdopted,function(){go({onlyAdopted:!ui.onlyAdopted});}));
      parts.push(h('div','chips',kc));
    }
    parts.push(box);
    fill();
    return h('div','lv',parts);
  }


  function saveErr(){ui.saving=false;ui.err='保存失败，数据未改动，请重试';redraw();}
  function run(fn,next){
    if(ui.saving)return;
    ui.saving=true;ui.err='';
    var nu=Object.assign({},ui,next||{},{saving:false,err:'',draft:null,form:'',confirm:''});
    commit(fn,nu).catch(saveErr);
  }
  function setAdopt(mid,vid){
    update(function(s){return patchMat(s,mid,function(m){return Object.assign({},m,{currentId:vid});});}).catch(function(){ui.err='保存失败，已保留原数据';redraw();});
  }
  function delVersion(mid,vid){
    run(function(s){return patchMat(s,mid,function(m){
      return Object.assign({},m,{versions:vers(m).filter(function(v){return v.id!==vid;}),currentId:m.currentId===vid?'':m.currentId});
    });},{view:'detail'});
  }
  function delMaterial(mid){
    run(function(s){return Object.assign({},s,{materials:mats(s).filter(function(m){return m.id!==mid;})});},{view:'list',sel:''});
  }
  function openNewMat(){
    var t=ui.topic&&ui.topic!==NONE?ui.topic:'';
    go({view:'form',form:'newMat',err:'',saving:false,draft:{name:'',kind:'table',topic:t,date:day(),location:'',note:'',adopt:false}});
  }
  function openEditMat(m){
    go({view:'form',form:'editMat',err:'',saving:false,draft:{name:m.name,kind:m.kind||'table',topic:topicOf(m)}});
  }
  function openNewVer(m){
    var nw=newestOf(m);
    go({view:'form',form:'newVer',err:'',saving:false,draft:{date:day(),location:nw?nw.location:'',note:'',adopt:false}});
  }
  function openEditVer(m,v){
    go({view:'form',form:'editVer',verId:v.id,err:'',saving:false,draft:{date:v.date,location:v.location,note:v.note||'',adopt:m.currentId===v.id}});
  }

  function verCard(m,v,only){
    var on=m.currentId===v.id;
    var cf=ui.confirm==='ver:'+v.id;
    var acts;
    if(cf){
      acts=h('div','vc-a',[h('span','ask',['删除这个版本记录？']),btn('确认删除',function(){delVersion(m.id,v.id);},{pri:true}),btn('取消',function(){go({confirm:''});})]);
    }else{
      acts=h('div','vc-a',[
        btn(on?'取消采用':'设为当前采用',function(){setAdopt(m.id,on?'':v.id);},{pri:!on}),
        btn('编辑',function(){openEditVer(m,v);}),
        only?null:btn('删除',function(){go({confirm:'ver:'+v.id});})
      ]);
    }
    return h('div','vc'+(on?' on':''),[
      h('div','vc-h',[h('b','vc-d',[v.date]),on?h('span','tag on',['当前采用']):null]),
      h('div','kv',[h('span','lb',['位置']),h('span','pth',[v.location])]),
      h('div','kv',[h('span','lb',['改动']),h('span','nt'+(v.note?'':' empty'),[v.note||'未记录'])]),
      acts
    ]);
  }

  function detailView(m){
    var sv=sortedVers(m),ad=adoptedOf(m),nw=sv[0];
    var hint;
    if(!ad)hint='还没有标记当前采用的版本';
    else if(nw&&nw.id!==ad.id&&nw.date>ad.date)hint='注意：有更新的版本 '+nw.date+' 还没有被采用';
    else hint=null;
    var delAsk=ui.confirm==='mat:'+m.id;
    var acts=delAsk?h('div','dv-a',[
      h('span','ask',['删除整份材料及其 '+sv.length+' 个版本记录？']),
      btn('确认删除',function(){delMaterial(m.id);},{pri:true}),
      btn('取消',function(){go({confirm:''});})
    ]):h('div','dv-a',[
